/* From Uiverse.io by BlackisPlay  - Tags: simple, animation, white, loading, loader, smooth, light */
.__UIV_SCOPE__ #timer {
  display: grid;
  grid-template-columns: repeat(3, 25px);
  grid-template-rows: repeat(5, 25px);
  gap: 10px;
  position: absolute;
  grid-template-areas:
    "div1 div2 div3"
    "div4 div5 div6"
    "div7 div8 div9"
    "div10 div11 div12"
    "div13 div14 div15";
}

.__UIV_SCOPE__ #div1,
.__UIV_SCOPE__ #div2,
.__UIV_SCOPE__ #div3,
.__UIV_SCOPE__ #div4,
.__UIV_SCOPE__ #div5,
