  background-color: rgb(243, 243, 243);
  border-radius: 5px;
}

.__UIV_SCOPE__ #div1 {
  grid-area: div1;
  animation: div1 10s both infinite;
}

@keyframes div1 {
  0% {
    transform: translateX(0);
